/* Responsive letter-spacing for headings to enhance visual impact */
h1 {
  font-family: "Display Font", sans-serif;
  font-size: 3.5em;
  letter-spacing: -0.04em; /* Slightly tighter for large headings */
}

/* Base letter-spacing for body text to improve readability */
p {
  font-family: "Body Text Font", sans-serif;
  font-size: 1.1em;
  line-height: 1.6;
  letter-spacing: 0.015em; /* A touch looser for better clarity */
}

/* Adjust for smaller screens or specific UI components */
@media (max-width: 768px) {
  h1 {
    font-size: 2.5em;
    letter-spacing: -0.02em; /* Less aggressive negative spacing on mobile */
  }
  p {
    font-size: 1em;
    letter-spacing: 0.02em; /* Potentially slightly looser for smaller text on screens */
  }
}

/* Example for a UI button or small text element */
.button-text {
  font-family: "UI Sans", sans-serif;
  font-size: 0.9em;
  text-transform: uppercase;
  letter-spacing: 0.08em; /* Often tighter or distinctly looser for uppercase UI elements */
}
